import shutil
import openpyxl
from datetime import datetime, time

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def time_fraction(value):
    if value is None:
        return None

    if isinstance(value, datetime):
        if value.tzinfo is not None:
            value = value.replace(tzinfo=None)
        delta = value - datetime.combine(value.date(), time.min)
        return delta.total_seconds() / 86400.0

    if isinstance(value, time):
        return (
            value.hour * 3600
            + value.minute * 60
            + value.second
            + value.microsecond / 1_000_000
        ) / 86400.0

    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return value % 1.0

    if isinstance(value, str):
        s = value.strip()
        formats = (
            "%d/%m/%Y %H:%M:%S",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%dT%H:%M:%S",
            "%H:%M:%S",
            "%d/%m/%Y %I:%M:%S %p",
            "%Y-%m-%d %I:%M:%S %p",
        )
        for fmt in formats:
            try:
                dt = datetime.strptime(s, fmt)
                delta = dt - datetime.combine(dt.date(), time.min)
                return delta.total_seconds() / 86400.0
            except ValueError:
                pass
        try:
            return float(s) % 1.0
        except ValueError:
            return None

    return None

for row in range(2, 5):
    src = vws.cell(row=row, column=9).value
    frac = time_fraction(src)
    cell = ws.cell(row=row, column=10)

    if frac is None:
        cell.value = None
    else:
        frac = frac % 1.0
        cell.value = frac
        cell.number_format = "hh:mm:ss AM/PM"

    print(row, repr(src), repr(frac))

wb.save(OUT)
